fn parse_optimized(content: String) -> Result<Document, String> {
    let mut stream = tokenize_optimized(content)
    let mut blocks = Vec::new()
    let mut title = "Untitled".to_string()

    // 타이틀 추출
    if let Some(token) = stream.peek() {
        if matches!(token.type, TokenType::Heading1) {
            if let Some(h1_token) = stream.next() {
                title = h1_token.content.clone()
            }
        }
    }

    // 블록 파싱 (스트림 기반)
    while let Some(token) = stream.peek() {
        match token.type {
            TokenType::Heading1 => {
                if let Some(h1) = stream.next() {
                    blocks.push(BlockType::Heading(1, h1.content))
