                if let Some(p) = stream.next() {
                    blocks.push(BlockType::Paragraph(p.content))
                }
            }
            TokenType::CodeBlockStart => {
                stream.next()  // skip opening ```
                let mut code_lines = Vec::new()
                while let Some(token) = stream.peek() {
                    if matches!(token.type, TokenType::CodeBlockEnd) {
                        stream.next()
                        break
                    }
                    if matches!(token.type, TokenType::CodeLine) {
                        if let Some(code_token) = stream.next() {
                            code_lines.push(code_token.content)
                        }
                    } else {
                        stream.next()
                    }
                }
                blocks.push(BlockType::CodeBlock(code_lines.join("\n")))
            }
            TokenType::OutputBlockStart => {
                stream.next()  // skip opening ```
                let mut output_lines = Vec::new()
                while let Some(token) = stream.peek() {
                    if matches!(token.type, TokenType::OutputBlockEnd) {
                        stream.next()
                        break
                    }
                    if matches!(token.type, TokenType::OutputLine) {
                        if let Some(output_token) = stream.next() {
                            output_lines.push(output_token.content)
                        }
                    } else {
                        stream.next()
                    }
                }
                blocks.push(BlockType::OutputBlock(output_lines.join("\n")))
            }
            TokenType::ListItem => {
                let mut items = Vec::new()
                while let Some(token) = stream.peek() {
                    if matches!(token.type, TokenType::ListItem) {
