        }
    })
}

// ============================================================================
// Cached Parser with Performance Tracking
// ============================================================================

struct OptimizedParser {
    cache: ParserCache,
    parse_time_ms: f64,
    token_count: i32
}

impl OptimizedParser {
    fn new() -> OptimizedParser {
        OptimizedParser {
            cache: ParserCache::new(),
            parse_time_ms: 0.0,
            token_count: 0
        }
    }

    fn parse_with_cache(&mut self, content: String, file_hash: String) -> Result<Document, String> {
        // 캐시 확인
        if let Some(cached_doc) = self.cache.get_cached_document(file_hash.clone()) {
            return Ok(cached_doc)
        }

        // 파싱
        let doc = parse_optimized(content)?

        // 캐시 저장
        self.cache.cache_document(file_hash, doc.clone())

        Ok(doc)
    }

    fn get_stats(&self) -> (i32, i32, f32) {
        self.cache.get_cache_stats()
    }
}

