// Public API with Performance Optimization
// ============================================================================

fn parse_flmd_optimized(content: String) -> Result<Document, String> {
    parse_optimized(content)
}

fn create_optimized_parser() -> OptimizedParser {
    OptimizedParser::new()
}

// ============================================================================
// Batch Processing
// ============================================================================

fn parse_multiple(documents: Vec<(String, String)>) -> Vec<Result<Document, String>> {
    let mut results = Vec::new()
    let mut parser = OptimizedParser::new()

    for (file_hash, content) in documents {
        match parser.parse_with_cache(content, file_hash) {
            Ok(doc) => results.push(Ok(doc)),
            Err(e) => results.push(Err(e))
        }
    }

    results
}

// ============================================================================
// Benchmarking
// ============================================================================

struct ParsingBenchmark {
    total_time: f64,
    document_count: i32,
    average_time: f64,
    cache_hit_rate: f32
}

fn benchmark_parser(documents: Vec<(String, String)>) -> ParsingBenchmark {
    let mut parser = OptimizedParser::new()
    let start = std::time::Instant::now()

    for (file_hash, content) in &documents {
        let _ = parser.parse_with_cache(content.clone(), file_hash.clone())
    }

    let total_time = start.elapsed().as_secs_f64() * 1000.0  // ms
    let doc_count = documents.len() as i32
    let avg_time = total_time / (doc_count as f64)
    let (_, _, hit_rate) = parser.get_stats()

    ParsingBenchmark {
        total_time: total_time,
        document_count: doc_count,
        average_time: avg_time,
        cache_hit_rate: hit_rate
    }
}

// ============================================================================
// Validation Improvements
// ============================================================================

fn validate_optimized(doc: Document) -> Result<Document, Vec<String>> {
    let mut errors = Vec::new()

    if doc.title.is_empty() {
        errors.push("Document title cannot be empty".to_string())
    }

    if doc.blocks.is_empty() {
        errors.push("Document must contain at least one block".to_string())
    }

    // 블록 순서 검증
    let mut prev_was_code = false
    for block in &doc.blocks {
        match block {
            BlockType::CodeBlock(_) => prev_was_code = true,
            BlockType::OutputBlock(_) => {
                if !prev_was_code {
                    errors.push("Output block must follow code block".to_string())
                }
                prev_was_code = false
            }
            _ => prev_was_code = false
        }
    }

    if errors.is_empty() {
        Ok(doc)
    } else {
        Err(errors)
    }
}

