        html.push_str(".output-title { color: #ff79c6; font-weight: bold; margin-bottom: 8px; }\n")
        html.push_str(".status-bar { background: #f0f0f0; padding: 5px 20px; display: flex; justify-content: space-between; font-size: 12px; border-top: 1px solid #ddd; height: 5%; }\n")
        html.push_str(".status-item { display: flex; gap: 20px; }\n")
        html.push_str("h1, h2, h3 { margin-top: 15px; margin-bottom: 10px; }\n")
        html.push_str(".markdown { line-height: 1.8; }\n")
        html.push_str("pre { background: #f5f5f5; padding: 10px; border-radius: 4px; overflow-x: auto; }\n")
        html.push_str("</style>\n</head>\n<body>\n")

        // Header
        html.push_str("<div class=\"header\">\n")
        html.push_str("<h1>Sovereign Workspace Editor</h1>\n")
        html.push_str("<div class=\"buttons\">\n")
        html.push_str("<button onclick=\"saveDocument()\">Save</button>\n")
        html.push_str("<button onclick=\"executeCode()\">Execute</button>\n")
        html.push_str("<button onclick=\"undoEdit()\">Undo</button>\n")
        html.push_str("<button onclick=\"redoEdit()\">Redo</button>\n")
        html.push_str("</div>\n</div>\n")

        // Main Container
        html.push_str("<div class=\"container\">\n")

        // Left Panel: Document
        html.push_str("<div class=\"left-panel markdown\">\n")
        html.push_str(&format!("<h1>{}</h1>\n", doc.title))
        for block in &doc.blocks {
            match block {
                BlockType::Heading(level, content) => {
                    html.push_str(&format!("<h{}>{}</h{}>\n", level + 1, content, level + 1))
                }
                BlockType::Paragraph(content) => {
                    html.push_str(&format!("<p>{}</p>\n", content))
                }
                BlockType::ListBlock(items) => {
                    html.push_str("<ul>\n")
                    for item in items {
                        html.push_str(&format!("<li>{}</li>\n", item))
                    }
                    html.push_str("</ul>\n")
                }
                BlockType::CodeBlock(code) => {
                    html.push_str("<pre><code>")
                    html.push_str(&code)
                    html.push_str("</code></pre>\n")
                }
                BlockType::OutputBlock(output) => {
                    html.push_str("<pre class=\"output\">")
                    html.push_str(&output)
                    html.push_str("</pre>\n")
                }
                _ => {}
            }
        }
        html.push_str("</div>\n")

        // Right Panel: Editor + Results
        html.push_str("<div class=\"right-panel\">\n")
        html.push_str("<div class=\"editor-section\">\n")
        html.push_str("<div class=\"editor-title\">Code Editor</div>\n")
        html.push_str("<pre class=\"code-editor\">\n")
        html.push_str(&editor.render_with_highlighting())
        html.push_str("</pre>\n")
        html.push_str("</div>\n")

        // Output Section
        html.push_str("<div class=\"output-section\">\n")
        html.push_str("<div class=\"output-title\">Output</div>\n")
        if let Some(result) = result {
            if result.success {
                html.push_str("<span style=\"color: #50fa7b;\">✓ Success</span>\n")
            } else {
                html.push_str(&format!("<span style=\"color: #ff79c6;\">✗ Error (code: {})</span>\n", result.exit_code))
            }
            html.push_str("<pre>")
            html.push_str(&result.stdout)
            if !result.stderr.is_empty() {
                html.push_str("STDERR:\n")
                html.push_str(&result.stderr)
            }
            html.push_str("</pre>\n")
        } else {
            html.push_str("<span style=\"color: #888;\">Ready to execute...</span>\n")
        }
        html.push_str("</div>\n")

        html.push_str("</div>\n</div>\n")

        // Status Bar
        let (lines, words, modified, chars, undo_count) = editor.get_stats()
        html.push_str("<div class=\"status-bar\">\n")
        html.push_str(&format!("<div class=\"status-item\"><span>Ln {}, Col 0</span><span>Words: {}</span><span>Chars: {}</span></div>\n", lines, words, chars))
        html.push_str(&format!("<div class=\"status-item\"><span>{}</span><span>Undo: {} steps</span></div>\n",
            if modified { "Modified" } else { "Saved" },
            undo_count))
        html.push_str("</div>\n")

        html.push_str("</body>\n</html>\n")

        html
    }
}

// ============================================================================
// Enhanced Editor Main Class
// ============================================================================

struct EnhancedEditor {
    state: EditorState,
    code_editor: EnhancedCodeEditor,
    layout: EnhancedEditorLayout,
    auto_save_enabled: bool,
    auto_save_interval: i32  // seconds
}

impl EnhancedEditor {
    fn new() -> EnhancedEditor {
        EnhancedEditor {
            state: EditorState {
                document: Document {
                    title: "Untitled".to_string(),
                    blocks: Vec::new(),
                    metadata: Metadata {
                        version: "0.2.0".to_string(),
                        created: "2026-03-18".to_string(),
                        modified: "2026-03-25".to_string()
                    }
                },
                current_file: "untitled.flmd".to_string(),
                is_modified: false,
                selected_block: None,
                cursor_position: (0, 0)
            },
            code_editor: EnhancedCodeEditor::new("fvlang".to_string()),
            layout: EnhancedEditorLayout::new(),
            auto_save_enabled: true,
            auto_save_interval: 60
        }
    }

    fn load_document(&mut self, content: String) -> Result<(), String> {
        let doc = parse_flmd_optimized(content)?
        self.state.document = doc
        self.state.is_modified = false
        Ok(())
    }

    fn render_html(&self) -> String {
        self.layout.render_html(
            self.state.document.clone(),
            &self.code_editor,
            None
        )
    }

    fn toggle_syntax_highlighting(&mut self) {
        self.code_editor.syntax_highlighting = !self.code_editor.syntax_highlighting
    }

    fn set_theme(&mut self, theme: String) {
        self.layout.with_theme(theme)
    }
}

