     1→// Phase 1 Week 2: Enhanced Editor UI
     2→// Syntax Highlighting + 성능 최적화
     3→
     4→// ============================================================================
     5→// Syntax Highlighting for FV-Lang
     6→// ============================================================================
     7→
     8→enum SyntaxType {
     9→    Keyword,        // fn, let, if, match, etc.
    10→    String,         // "..."
    11→    Number,         // 123, 3.14
    12→    Comment,        // // comment
    13→    Identifier,     // variable names
    14→    Operator,       // +, -, *, /, =
    15→    Type,           // i32, String, Vec
    16→    Punctuation     // {}, [], (), ;
    17→}
    18→
    19→struct HighlightRule {
    20→    pattern: String,
    21→    syntax_type: SyntaxType,
    22→    color: String
    23→}
    24→
    25→fn create_fvlang_highlighter() -> Vec<HighlightRule> {
    26→    vec![
    27→        HighlightRule {
    28→            pattern: "\\bfn\\b".to_string(),
    29→            syntax_type: SyntaxType::Keyword,
    30→            color: "#ff79c6".to_string()  // 핑크
    31→        },
    32→        HighlightRule {
    33→            pattern: "\\blet\\b".to_string(),
    34→            syntax_type: SyntaxType::Keyword,
    35→            color: "#ff79c6".to_string()
    36→        },
    37→        HighlightRule {
    38→            pattern: "\\bif\\b|\\belse\\b|\\bmatch\\b".to_string(),
    39→            syntax_type: SyntaxType::Keyword,
    40→            color: "#ff79c6".to_string()
    41→        },
    42→        HighlightRule {
    43→            pattern: "\\bstruct\\b|\\benum\\b|\\bimpl\\b".to_string(),
    44→            syntax_type: SyntaxType::Keyword,
    45→            color: "#ff79c6".to_string()
    46→        },
    47→        HighlightRule {
    48→            pattern: "\"[^\"]*\"".to_string(),
    49→            syntax_type: SyntaxType::String,
    50→            color: "#f1fa8c".to_string()  // 노랑
    51→        },
    52→        HighlightRule {
    53→            pattern: "//.*$".to_string(),
    54→            syntax_type: SyntaxType::Comment,
    55→            color: "#6272a4".to_string()  // 회색
    56→        },
    57→        HighlightRule {
    58→            pattern: "[0-9]+(\\.[0-9]+)?".to_string(),
    59→            syntax_type: SyntaxType::Number,
    60→            color: "#bd93f9".to_string()  // 보라
    61→        },
    62→        HighlightRule {
    63→            pattern: "i32|i64|f32|f64|String|Vec|bool".to_string(),
    64→            syntax_type: SyntaxType::Type,
    65→            color: "#8be9fd".to_string()  // 파랑
    66→        }
    67→    ]
    68→}
    69→
    70→fn apply_syntax_highlighting(code: String) -> String {
    71→    let rules = create_fvlang_highlighter()
    72→    let mut highlighted = code.clone()
    73→
    74→    for rule in rules {
    75→        // 정규식 매칭 및 색상 적용
    76→        // (실제 구현에서는 regex 라이브러리 사용)
    77→    }
    78→
    79→    highlighted
    80→}
    81→
    82→// ============================================================================
    83→// Improved Code Editor with Diff Support
    84→// ============================================================================
    85→
    86→struct CodeDiff {
    87→    original: String,
    88→    modified: String,
    89→    lines_added: i32,
    90→    lines_removed: i32
    91→}
    92→
    93→impl CodeDiff {
    94→    fn compute(original: String, modified: String) -> CodeDiff {
    95→        let orig_lines = original.lines().count() as i32
    96→        let mod_lines = modified.lines().count() as i32
    97→
    98→        CodeDiff {
    99→            original: original,
   100→            modified: modified,
   101→            lines_added: std::cmp::max(0, mod_lines - orig_lines),
   102→            lines_removed: std::cmp::max(0, orig_lines - mod_lines)
   103→        }
   104→    }
   105→
   106→    fn has_changes(&self) -> bool {
   107→        self.lines_added > 0 || self.lines_removed > 0
   108→    }
   109→}
   110→
   111→struct EnhancedCodeEditor {
   112→    content: String,
   113→    language: String,
   114→    line_numbers: bool,
   115→    syntax_highlighting: bool,
   116→    line_count: i32,
   117→    modified: bool,
   118→    saved_content: String,
   119→    undo_stack: Vec<String>,
   120→    redo_stack: Vec<String>,
   121→    diff: Option<CodeDiff>
   122→}
   123→
   124→impl EnhancedCodeEditor {
   125→    fn new(language: String) -> EnhancedCodeEditor {
   126→        EnhancedCodeEditor {
   127→            content: String::new(),
   128→            language: language,
   129→            line_numbers: true,
   130→            syntax_highlighting: true,
   131→            line_count: 1,
   132→            modified: false,
   133→            saved_content: String::new(),
   134→            undo_stack: Vec::new(),
   135→            redo_stack: Vec::new(),
   136→            diff: None
   137→        }
   138→    }
   139→
   140→    fn set_content(&mut self, content: String) {
   141→        // 변경 사항 저장 (undo용)
   142→        if !self.content.is_empty() {
   143→            self.undo_stack.push(self.content.clone())
   144→        }
   145→
   146→        self.line_count = content.lines().count() as i32
   147→        self.content = content
   148→        self.modified = true
   149→        self.redo_stack.clear()
   150→    }
   151→
   152→    fn undo(&mut self) -> bool {
   153→        if let Some(prev) = self.undo_stack.pop() {
   154→            self.redo_stack.push(self.content.clone())
   155→            self.content = prev
   156→            self.modified = true
   157→            true
   158→        } else {
   159→            false
   160→        }
   161→    }
   162→
   163→    fn redo(&mut self) -> bool {
   164→        if let Some(next) = self.redo_stack.pop() {
   165→            self.undo_stack.push(self.content.clone())
   166→            self.content = next
   167→            self.modified = true
   168→            true
   169→        } else {
   170→            false
   171→        }
   172→    }
   173→
   174→    fn save(&mut self) {
   175→        self.saved_content = self.content.clone()
   176→        self.modified = false
   177→    }
   178→
   179→    fn compute_diff(&mut self) {
   180→        self.diff = Some(CodeDiff::compute(self.saved_content.clone(), self.content.clone()))
   181→    }
   182→
   183→    fn render_with_highlighting(&self) -> String {
   184→        let mut output = String::new()
   185→
   186→        if self.syntax_highlighting {
   187→            for (i, line) in self.content.lines().enumerate() {
   188→                if self.line_numbers {
   189→                    output.push_str(&format!("{:<4} │ ", i + 1))
   190→                }
   191→
   192→                // 문법 강조 적용
   193→                let highlighted = apply_syntax_highlighting(line.to_string())
   194→                output.push_str(&highlighted)
   195→                output.push_str("\n")
   196→            }
   197→        } else {
   198→            for (i, line) in self.content.lines().enumerate() {
   199→                if self.line_numbers {
