    28→fn render_markdown(block: BlockType) -> String {
    29→    match block {
    30→        BlockType::Heading(level, content) => {
    31→            let prefix = "#".repeat(level as usize)
    32→            format!("{} {}", prefix, content)
    33→        }
    34→        BlockType::Paragraph(content) => {
    35→            format!("{}", content)
    36→        }
    37→        BlockType::ListBlock(items) => {
    38→            let mut result = String::new()
    39→            for item in items {
    40→                result.push_str(&format!("- {}\n", item))
    41→            }
    42→            result
    43→        }
    44→        BlockType::CodeBlock(code) => {
    45→            format!("```fvlang\n{}\n```", code)
    46→        }
    47→        BlockType::OutputBlock(output) => {
    48→            format!("```output\n{}\n```", output)
    49→        }
    50→        _ => String::new()
    51→    }
    52→}
