   107→}
   108→
   109→impl CodeEditor {
   110→    fn new(language: String) -> CodeEditor {
   111→        CodeEditor {
   112→            content: String::new(),
   113→            language: language,
   114→            line_numbers: true,
   115→            line_count: 1
   116→        }
   117→    }
