   119→    fn set_content(&mut self, content: String) {
   120→        self.line_count = content.lines().count() as i32
   121→        self.content = content
   122→    }
   123→
   124→    fn append_line(&mut self, line: String) {
   125→        self.content.push_str(&line)
   126→        self.content.push_str("\n")
   127→        self.line_count = self.line_count + 1
   128→    }
   129→
   130→    fn get_line(&self, line_num: i32) -> Option<String> {
   131→        let lines: Vec<&str> = self.content.lines().collect()
   132→        if line_num >= 0 && (line_num as usize) < lines.len() {
   133→            Some(lines[line_num as usize].to_string())
   134→        } else {
   135→            None
   136→        }
   137→    }
   138→
   139→    fn render_with_syntax(&self) -> String {
   140→        let mut output = String::new()
   141→
   142→        if self.line_numbers {
   143→            for (i, line) in self.content.lines().enumerate() {
   144→                output.push_str(&format!("{:<4} | {}\n", i + 1, line))
   145→            }
   146→        } else {
   147→            output = self.content.clone()
   148→        }
   149→
   150→        output
   151→    }
   152→}
