    83→// Improved Code Editor with Diff Support
    84→// ============================================================================
    85→
    86→struct CodeDiff {
    87→    original: String,
    88→    modified: String,
    89→    lines_added: i32,
    90→    lines_removed: i32
    91→}
    92→
    93→impl CodeDiff {
    94→    fn compute(original: String, modified: String) -> CodeDiff {
    95→        let orig_lines = original.lines().count() as i32
    96→        let mod_lines = modified.lines().count() as i32
    97→
    98→        CodeDiff {
    99→            original: original,
   100→            modified: modified,
   101→            lines_added: std::cmp::max(0, mod_lines - orig_lines),
   102→            lines_removed: std::cmp::max(0, orig_lines - mod_lines)
   103→        }
   104→    }
   105→
   106→    fn has_changes(&self) -> bool {
   107→        self.lines_added > 0 || self.lines_removed > 0
   108→    }
   109→}
