            intent_type: IntentType::Compute,
            weight: 1.0
        },
        // Transform
        PatternRule {
            keywords: vec!["변환".to_string(), "convert".to_string(),
                           "transform".to_string(), "바꾸다".to_string()],
            intent_type: IntentType::Transform,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["대문자".to_string(), "소문자".to_string(),
                           "uppercase".to_string(), "lowercase".to_string()],
            intent_type: IntentType::Transform,
            weight: 0.9
        },
        // Filter
        PatternRule {
            keywords: vec!["필터".to_string(), "filter".to_string(),
                           "걸러".to_string(), "조건".to_string(), "where".to_string()],
            intent_type: IntentType::Filter,
